def legacy_month(sheet_name: str) -> int | None:
    normalized = plain(sheet_name)
    prefixes = {"JAN": 1, "FEV": 2, "MAR": 3, "ABR": 4, "MAI": 5, "JUN": 6,
                "JUL": 7, "AGO": 8, "SET": 9, "OUT": 10, "NOV": 11, "DEZ": 12}
    return next((month for prefix, month in prefixes.items() if normalized.startswith(prefix)), None)


def parse_legacy_workbook(raw: bytes, filename: str, year: int) -> pd.DataFrame:
    """Convert the old monthly matrix to the app's normalized balance rows."""
    try:
        import openpyxl
        workbook = openpyxl.load_workbook(io.BytesIO(raw), data_only=True, read_only=True)
    except Exception as exc:
        raise RuntimeError("Não foi possível abrir a planilha histórica.") from exc

    rows: list[dict[str, Any]] = []
    for sheet in workbook.worksheets:
        month = legacy_month(sheet.title)
        if month is None:
            continue
        for row_number in range(4, min(sheet.max_row or 40, 40) + 1):
            raw_day = sheet.cell(row_number, 1).value
            if isinstance(raw_day, (datetime, date)):
                day_number = raw_day.day
            else:
                match = re.match(r"\s*(\d{1,2})(?:\D|$)", str(raw_day or ""))
                day_number = int(match.group(1)) if match else 0
            if not 1 <= day_number <= 31:
                continue
            try:
                position = date(year, month, day_number)
            except ValueError:
                continue
            for column, (company, bank, account) in LEGACY_COLUMNS.items():
                balance = parse_brl(sheet.cell(row_number, column).value)
                if balance is None:
                    continue
                rows.append({
                    "Salvar": True,
                    "Data": position,
                    "Empresa": company,
                    "Banco": bank,
                    "Agência": "1231-9" if bank == "Banco do Brasil" else "",
                    "Conta": account,
                    "Saldo identificado": br_number(balance),
                    "Status": "Histórico pronto para importar",
                    "Arquivo": filename,
                    "Confiança": "Histórico",
                    "Origem": "Importação histórica XLSX",
                })
    return pd.DataFrame(rows)


@st.cache_resource(show_spinner=False)
def sheets_client():
    try:
        import gspread
        from google.oauth2.service_account import Credentials
    except ImportError as exc:
        raise RuntimeError("Dependências do Google Sheets não instaladas.") from exc

    secrets = None
    try:
        for name in ("google_service_account", "gcp_service_account"):
            if name in st.secrets:
                secrets = dict(st.secrets[name])
                break
    except Exception:
        secrets = None
    if not secrets:
        raise RuntimeError(
            "Credencial do Google não configurada. Adicione a seção [google_service_account] "
            "aos Secrets do Streamlit e compartilhe a planilha com o e-mail client_email."
        )
    required = {"type", "project_id", "private_key", "client_email", "token_uri"}
    missing = sorted(required - set(secrets))
    if missing:
        raise RuntimeError("Credencial incompleta. Campos ausentes: " + ", ".join(missing))
    credentials = Credentials.from_service_account_info(
        secrets,
        scopes=["https://www.googleapis.com/auth/spreadsheets"],
    )
    return gspread.authorize(credentials)


def get_book():
    return sheets_client().open_by_key(SPREADSHEET_ID)


def ensure_worksheet(book, title: str, headers: list[str], rows: int = 1000):
    import gspread
    try:
        ws = book.worksheet(title)
    except gspread.WorksheetNotFound:
        ws = book.add_worksheet(title=title, rows=rows, cols=max(12, len(headers)))
    values = ws.get_all_values()
    if not values:
        ws.append_row(headers, value_input_option="RAW")
    elif values[0] != headers:
        ws.update(range_name=f"A1:{chr(64 + len(headers))}1", values=[headers])
    return ws


def ensure_database():
    book = get_book()
    contas_ws = ensure_worksheet(book, "CONTAS", CONTAS_HEADERS, 100)
    saldos_ws = ensure_worksheet(book, "SALDOS", SALDOS_HEADERS, 5000)
    existing = contas_ws.get_all_records()
    existing_keys = {
        (key_part(row.get("BANCO")), key_part(row.get("AGENCIA")), key_part(row.get("CONTA")))
        for row in existing
    }
    new_rows = [list(row) for row in CONTAS_INICIAIS if (key_part(row[1]), key_part(row[2]), key_part(row[3])) not in existing_keys]
    if new_rows:
        contas_ws.append_rows(new_rows, value_input_option="USER_ENTERED")
    return contas_ws, saldos_ws


@st.cache_data(ttl=60, show_spinner=False)
def load_database(_refresh: int = 0) -> tuple[pd.DataFrame, pd.DataFrame]:
    contas_ws, saldos_ws = ensure_database()
    contas = pd.DataFrame(contas_ws.get_all_records(), columns=CONTAS_HEADERS)
    saldos = pd.DataFrame(saldos_ws.get_all_records(), columns=SALDOS_HEADERS)
    if not saldos.empty:
        # SALDO is persisted as integer cents. This avoids decimal-separator changes
        # caused by the spreadsheet locale (for example, 106531.91 -> 10653191).
        saldos["SALDO"] = saldos["SALDO"].map(parse_brl).map(
            lambda value: value / 100 if value is not None else None
        )
        saldos["DATA_DT"] = pd.to_datetime(saldos["DATA"], dayfirst=True, errors="coerce")
    return contas, saldos


def local_accounts() -> pd.DataFrame:
    return pd.DataFrame(CONTAS_INICIAIS, columns=CONTAS_HEADERS)


def get_accounts() -> pd.DataFrame:
    try:
        contas, _ = load_database(st.session_state.get("db_refresh", 0))
        return contas if not contas.empty else local_accounts()
    except Exception:
        return local_accounts()


def preprocess_image(raw: bytes | Image.Image) -> Image.Image:
    image = raw.copy() if isinstance(raw, Image.Image) else Image.open(io.BytesIO(raw))
    image = ImageOps.exif_transpose(image).convert("L")
    if image.width < 1800:
        scale = 1800 / image.width
        image = image.resize((1800, int(image.height * scale)), Image.Resampling.LANCZOS)
    image = ImageOps.autocontrast(image, cutoff=1)
    image = ImageEnhance.Contrast(image).enhance(1.35)
    return image.filter(ImageFilter.SHARPEN)


def preprocess_crop(image: Image.Image, box: tuple[int, int, int, int], invert: bool = False) -> Image.Image:
    """Prepare a small screen region without losing the tiny header characters."""
    crop = ImageOps.exif_transpose(image).convert("L").crop(box)
    scale = max(3.0, 2200 / max(crop.width, 1))
    crop = crop.resize((int(crop.width * scale), int(crop.height * scale)), Image.Resampling.LANCZOS)
    crop = ImageOps.autocontrast(crop, cutoff=1)
    crop = ImageEnhance.Contrast(crop).enhance(1.7)
    if invert:
        crop = ImageOps.invert(crop)
    return crop.filter(ImageFilter.SHARPEN)


def ocr_image(image: Image.Image, psm: int = 6, whitelist: str | None = None) -> str:
    try:
        import pytesseract
        config = f"--oem 3 --psm {psm}"
        if whitelist:
            config += f" -c tessedit_char_whitelist={whitelist}"
        try:
            return pytesseract.image_to_string(image, lang="por+eng", config=config)
        except pytesseract.TesseractError:
            return pytesseract.image_to_string(image, lang="eng", config=config)
    except Exception as exc:
        raise RuntimeError(
            "OCR indisponível. Confirme que tesseract-ocr e tesseract-ocr-por estão no packages.txt."
        ) from exc


def known_match(found: str, accounts: pd.DataFrame, bank: str) -> dict[str, Any] | None:
    target = key_part(found)
    subset = accounts[accounts["BANCO"].map(plain).str.contains(plain(bank), regex=False)]
    best: tuple[float, dict[str, Any] | None] = (0.0, None)
    for row in subset.to_dict("records"):
        candidate = key_part(row["CONTA"])
        score = SequenceMatcher(None, target, candidate).ratio()
        if target == candidate:
            score = 1.0
        if score > best[0]:
            best = (score, row)
    return best[1] if best[0] >= 0.68 else None


MONEY_PATTERN = r"(?:R\$\s*)?[-(]?\d{1,3}(?:\.\d{3})*,\d{2}[)-]?"


def match_bb_account(texts: list[str], accounts: pd.DataFrame) -> tuple[dict[str, Any] | None, bool]:
    """Match the header against the five known accounts, tolerating OCR substitutions."""
    subset = accounts[accounts["BANCO"].map(plain).str.contains("BANCO DO BRASIL", regex=False)]
    rows = subset.to_dict("records")
    translation = str.maketrans({"O": "0", "I": "1", "L": "1", "S": "5", "B": "8", "Z": "2"})

    compact_texts = [key_part(plain(text)).translate(translation) for text in texts if text]
    for compact in compact_texts:
        for row in rows:
            expected = key_part(row["CONTA"]).translate(translation)
            if expected in compact:
                return row, True

    best_score = 0.0
    best_row = None
    for compact in compact_texts:
        for row in rows:
            expected = key_part(row["CONTA"]).translate(translation)
            size = len(expected)
            for width in (size - 1, size, size + 1):
                if width < 4:
                    continue
                for start in range(max(1, len(compact) - width + 1)):
                    score = SequenceMatcher(None, compact[start:start + width], expected).ratio()
                    if score > best_score:
                        best_score, best_row = score, row
    return (best_row, False) if best_score >= 0.80 else (None, False)


def final_bb_balance(texts: list[str]) -> float | None:
    # First choice: the final line explicitly labelled "Saldo".
    labelled: list[float] = []
    for text in texts:
        for line in text.splitlines():
            line_plain = plain(line).strip()
            if re.match(r"^SALD[O0]\b", line_plain) and "999" not in line_plain:
                values = re.findall(MONEY_PATTERN, line, flags=re.I)
                if values:
                    value = parse_brl(values[-1])
                    if value is not None:
                        labelled.append(value)
    if labelled:
        return labelled[-1]

    # In these BB screenshots the final balance is the last monetary value in the footer.
    # This fallback only receives footer OCR, so it cannot pick a transaction from the top.
    for text in texts:
        values = re.findall(MONEY_PATTERN, text, flags=re.I)
        if values:
            value = parse_brl(values[-1])
            if value is not None:
                return value
    return None


def extract_bb(raw: bytes, filename: str, accounts: pd.DataFrame) -> list[dict[str, Any]]:
    original = ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert("RGB")
    width, height = original.size

    # The account is in the blue header. Upscaling and inverting that region gives
    # Tesseract dark characters on a light background instead of a complex full screen.
    header_box = (int(width * 0.50), 0, width, min(height, max(80, int(height * 0.23))))
    header = preprocess_crop(original, header_box, invert=True)
    header_texts = [ocr_image(header, psm=6), ocr_image(header, psm=11)]
    account, exact = match_bb_account(header_texts, accounts)

    full_text = ""
    if not account:
        full_text = ocr_image(preprocess_image(original), psm=11)
        account, exact = match_bb_account(header_texts + [full_text], accounts)
    if not account:
        return [result_row(filename=filename, bank="Banco do Brasil", status="Conta não identificada", confidence="Baixa")]

    # Read only the lower part for the final balance. Two layout modes handle both
    # the aligned table and sparse footer text used by the Banco do Brasil page.
    footer_box = (0, int(height * 0.52), width, height)
    footer = preprocess_crop(original, footer_box)
    footer_texts = [ocr_image(footer, psm=6), ocr_image(footer, psm=11)]
    saldo = final_bb_balance(footer_texts)
    if saldo is None:
        if not full_text:
            full_text = ocr_image(preprocess_image(original), psm=6)
        saldo = final_bb_balance([full_text])
    if saldo is None:
        return [result_row(account, filename, "Banco do Brasil", status="Saldo não localizado", confidence="Média")]
    return [result_row(account, filename, "Banco do Brasil", saldo, "Leitura concluída", "Alta" if exact else "Média")]


def extract_pdf_text(raw: bytes) -> tuple[str, str]:
    try:
        import fitz
        doc = fitz.open(stream=raw, filetype="pdf")
    except Exception as exc:
        raise RuntimeError("Arquivo PDF inválido ou corrompido.") from exc
    direct = "\n".join(page.get_text("text") for page in doc)
    if len(re.sub(r"\s", "", direct)) >= 100:
        return direct, "Texto do PDF"
    pages = []
    for page in doc:
        pix = page.get_pixmap(matrix=fitz.Matrix(2.4, 2.4), alpha=False)
        image = Image.open(io.BytesIO(pix.tobytes("png")))
        pages.append(ocr_image(preprocess_image(image), psm=6))
    return "\n".join(pages), "OCR do PDF"


def tolerant_account_pattern(account: str) -> str:
    chars = [re.escape(ch) for ch in key_part(account)]
    return r"[.\s\-/]*".join(chars)


def find_target_balance(block: str) -> float | None:
    lines = block.splitlines()
    for line in lines:
        normalized = plain(line)
        has_target = ("SDO" in normalized and "DISP" in normalized and "APLIC" in normalized and "HOJE" in normalized)
        if has_target:
            values = re.findall(MONEY_PATTERN, line, flags=re.I)
            if values:
                return parse_brl(values[-1])
    # OCR sometimes breaks the label and amount across two lines.
    compact = re.sub(r"\s+", " ", plain(block))
    match = re.search(r"SD[O0].{0,12}DISP.{0,12}APLIC.{0,12}HOJE.{0,20}?(" + MONEY_PATTERN + r")", compact)
    return parse_brl(match.group(1)) if match else None


def extract_itau(raw: bytes, filename: str, accounts: pd.DataFrame) -> list[dict[str, Any]]:
    text, origin = extract_pdf_text(raw)
    subset = accounts[accounts["BANCO"].map(plain).str.contains("ITAU", regex=False)].copy()
    positions: list[tuple[int, dict[str, Any]]] = []
    for account in subset.to_dict("records"):
        match = re.search(tolerant_account_pattern(str(account["CONTA"])), plain(text))
        if match:
            positions.append((match.start(), account))
    positions.sort(key=lambda item: item[0])
    if not positions:
        return [result_row(filename=filename, bank="Itaú", status="Conta não identificada", confidence="Baixa", origin=origin)]

    rows = []
    for idx, (start, account) in enumerate(positions):
        end = positions[idx + 1][0] if idx + 1 < len(positions) else len(text)
        block = text[start:end]
        saldo = find_target_balance(block)
        if saldo is None:
            rows.append(result_row(account, filename, "Itaú", status="Saldo não localizado", confidence="Média", origin=origin))
        else:
            rows.append(result_row(account, filename, "Itaú", saldo, "Leitura concluída", "Alta", origin))
    return rows


def result_row(
    account: dict[str, Any] | None = None,
    filename: str = "",
    bank: str = "",
    balance: float | None = None,
    status: str = "Arquivo inválido",
    confidence: str = "Baixa",
    origin: str = "OCR",
) -> dict[str, Any]:
    account = account or {}
    return {
        "Salvar": balance is not None,
        "Empresa": account.get("EMPRESA", ""),
        "Banco": bank or account.get("BANCO", ""),
        "Agência": str(account.get("AGENCIA", "")),
        "Conta": str(account.get("CONTA", "")),
        "Saldo identificado": balance,
        "Status": status,
        "Arquivo": filename,
        "Confiança": confidence,
        "Origem": origin,
    }


def process_file(uploaded, accounts: pd.DataFrame) -> list[dict[str, Any]]:
    raw = uploaded.getvalue()
    name = uploaded.name
    ext = name.rsplit(".", 1)[-1].lower() if "." in name else ""
    try:
        if ext == "pdf":
            return extract_itau(raw, name, accounts)
        if ext in {"png", "jpg", "jpeg", "webp", "tif", "tiff"}:
            return extract_bb(raw, name, accounts)
        return [result_row(filename=name, status="Arquivo inválido")]
    except Exception as exc:
        return [result_row(filename=name, status=f"Não foi possível identificar o saldo deste arquivo. ({exc})")]


def save_balances(rows: pd.DataFrame, position_date: date | None = None) -> tuple[int, int]:
    _, ws = ensure_database()
    values = ws.get_all_values()
    index: dict[tuple[str, str, str], int] = {}
    for sheet_row, row in enumerate(values[1:], start=2):
        padded = row + [""] * (len(SALDOS_HEADERS) - len(row))
        record = dict(zip(SALDOS_HEADERS, padded))
        index[(record["DATA"], key_part(record["BANCO"]), key_part(record["CONTA"]))] = sheet_row

    updates: list[dict[str, Any]] = []
    appends: list[list[Any]] = []
    for _, row in rows.iterrows():
        balance = parse_brl(row["Saldo identificado"])
        if not bool(row["Salvar"]) or balance is None or not str(row["Conta"]).strip():
            continue
        row_date = position_date if position_date is not None else row.get("Data")
        if isinstance(row_date, datetime):
            row_date = row_date.date()
        if not isinstance(row_date, date):
            parsed_date = pd.to_datetime(row_date, dayfirst=True, errors="coerce")
            if pd.isna(parsed_date):
                continue
            row_date = parsed_date.date()
        date_text = row_date.strftime("%d/%m/%Y")
        balance_cents = int(round(balance * 100))
        key = (date_text, key_part(row["Banco"]), key_part(row["Conta"]))
        stable_id = hashlib.sha1("|".join(key).encode("utf-8")).hexdigest()[:16]
        payload = [
            stable_id, date_text, row["Empresa"], row["Banco"], row["Agência"], row["Conta"],
            balance_cents, row["Arquivo"], row.get("Origem", "OCR"), row.get("Confiança", ""),
            datetime.now().strftime("%d/%m/%Y %H:%M:%S"),
        ]
        if key in index:
            sheet_row = index[key]
            updates.append({"range": f"A{sheet_row}:K{sheet_row}", "values": [payload]})
        else:
            appends.append(payload)
            index[key] = len(values) + len(appends)
    # RAW preserves integer cents regardless of the spreadsheet locale. Batching is
    # essential for historical imports so hundreds of rows use only two API calls.
    if updates:
        ws.batch_update(updates, value_input_option="RAW")
    if appends:
        ws.append_rows(appends, value_input_option="RAW")
    st.session_state["db_refresh"] = st.session_state.get("db_refresh", 0) + 1
    load_database.clear()
    return len(appends), len(updates)


def page_update() -> None:
    hero("Atualizar saldos", "Envie os documentos do dia, confira os valores e confirme a atualização.")
    left, right = st.columns([1, 2])
    with left:
        position_date = st.date_input("Data da posição", value=date.today(), format="DD/MM/YYYY")
    with right:
        uploads = st.file_uploader(
            "PDF do Itaú e imagens do Banco do Brasil",
            type=["pdf", "png", "jpg", "jpeg", "webp", "tif", "tiff"],
            accept_multiple_files=True,
        )
    if st.button("Ler documentos", type="primary", disabled=not uploads, use_container_width=True):
        accounts = get_accounts()
        progress = st.progress(0, text="Preparando leitura…")
        results: list[dict[str, Any]] = []
        for idx, uploaded in enumerate(uploads):
            progress.progress(idx / len(uploads), text=f"Lendo {uploaded.name}")
            results.extend(process_file(uploaded, accounts))
        progress.progress(1.0, text="Leitura concluída")
        st.session_state["review_rows"] = results
        st.session_state["position_date"] = position_date

    if "review_rows" not in st.session_state:
        st.info("Selecione os arquivos e clique em **Ler documentos**.")
        return

    st.subheader("Conferência")
    review = pd.DataFrame(st.session_state["review_rows"])
    display_columns = ["Salvar", "Empresa", "Banco", "Agência", "Conta", "Saldo identificado", "Status", "Arquivo"]
    review_display = review[display_columns].copy()
    review_display["Saldo identificado"] = review_display["Saldo identificado"].map(br_number)
    edited = st.data_editor(
        review_display,
        hide_index=True,
        use_container_width=True,
        num_rows="fixed",
        disabled=["Empresa", "Banco", "Agência", "Conta", "Status", "Arquivo"],
        column_config={
            "Salvar": st.column_config.CheckboxColumn(default=False),
            "Saldo identificado": st.column_config.TextColumn(
                "Saldo identificado",
                help="Use o formato brasileiro, por exemplo: 106.531,91",
            ),
        },
        key="review_editor",
    )
    total = edited.loc[edited["Salvar"], "Saldo identificado"].map(parse_brl).dropna().sum()
    st.metric("Total dos saldos selecionados", brl(total))
    if st.button("Confirmar atualização", type="primary", use_container_width=True):
        selected = edited[edited["Salvar"]].copy()
        invalid = selected["Saldo identificado"].map(parse_brl).isna() | selected["Conta"].astype(str).str.strip().eq("")
        if selected.empty:
            st.warning("Selecione ao menos uma linha para salvar.")
        elif invalid.any():
            st.error("Preencha conta e saldo em todas as linhas selecionadas.")
        else:
            for extra in ("Confiança", "Origem"):
                edited[extra] = review[extra].values
            try:
                with st.spinner("Atualizando Google Sheets…"):
                    inserted, updated = save_balances(edited, st.session_state.get("position_date", position_date))
                st.success(f"Atualização concluída: {inserted} novo(s) registro(s) e {updated} atualizado(s).")
            except Exception as exc:
                st.error(str(exc))


def page_history_import() -> None:
    hero("Importar histórico", "Traga a planilha mensal antiga para o mesmo histórico usado pelo painel.")
    st.info(
        "As colunas consolidadas do Itaú serão preservadas como grupos históricos. "
        "Os valores não serão distribuídos artificialmente entre contas individuais."
    )
    left, right = st.columns([1, 2])
    with left:
        history_year = st.number_input("Ano da planilha", min_value=2020, max_value=2100, value=2026, step=1)
    with right:
        workbook_file = st.file_uploader("Planilha histórica (.xlsx)", type=["xlsx"], key="history_workbook")

    if st.button("Analisar planilha", type="primary", disabled=workbook_file is None, use_container_width=True):
        try:
            with st.spinner("Lendo meses e consolidando o histórico…"):
                history = parse_legacy_workbook(workbook_file.getvalue(), workbook_file.name, int(history_year))
            if history.empty:
                st.warning("Nenhum saldo diário foi encontrado no formato esperado.")
                st.session_state.pop("history_rows", None)
            else:
                st.session_state["history_rows"] = history
        except Exception as exc:
            st.error(str(exc))

    history = st.session_state.get("history_rows")
    if history is None or history.empty:
        return
    st.subheader("Prévia da importação")
    summary = (
        history.assign(Mês=history["Data"].map(lambda value: value.strftime("%m/%Y")))
        .groupby("Mês", as_index=False)
        .agg(Dias=("Data", "nunique"), Registros=("Conta", "size"))
    )
    st.dataframe(summary, hide_index=True, use_container_width=True)
    preview = history[["Data", "Empresa", "Banco", "Conta", "Saldo identificado"]].copy()
    preview["Data"] = preview["Data"].map(lambda value: value.strftime("%d/%m/%Y"))
    st.dataframe(preview, hide_index=True, use_container_width=True, height=360)
    st.caption(f"{len(history)} registros encontrados. Registros já existentes serão atualizados pela chave data + banco + conta.")
    if st.button("Importar histórico para o Google Sheets", type="primary", use_container_width=True):
        try:
            with st.spinner("Gravando histórico em lote…"):
                inserted, updated = save_balances(history, position_date=None)
            st.success(f"Histórico importado: {inserted} novo(s) registro(s) e {updated} atualizado(s).")
        except Exception as exc:
            st.error(str(exc))


def password_gate() -> bool:
    if st.session_state.get("dashboard_unlocked"):
        return True
    st.subheader("Acesso protegido")
    with st.form("password_form"):
        password = st.text_input("Senha", type="password")
        sent = st.form_submit_button("Entrar", type="primary")
    try:
        expected = st.secrets.get("dashboard_password", "Dauto@10.10")
    except Exception:
        expected = "Dauto@10.10"
    if sent:
        if password == expected:
            st.session_state["dashboard_unlocked"] = True
            st.rerun()
        else:
            st.error("Senha incorreta.")
    return False


def _money_class(value: float) -> str:
    return "negative" if value < 0 else "positive" if value > 0 else "zero"


def render_daily_software_table(display: pd.DataFrame) -> None:
    account_map = {"ÚNICA ITAÚ":"73733-7","ÚNICA BB":"62.608-2","MERCADO ITAÚ":"ITAÚ","MERCADO BB":"33.300-X","V&T ITAÚ":"ITAÚ","V&T BB":"62.619-8","ÉTICA ITAÚ":"ITAÚ","ÉTICA BB":"62.686-4","DT TINTAS ITAÚ":"ITAÚ","DT TINTAS BB":"62.810-7","DAUTO ITAÚ":"ITAÚ","DAUTO BB":"BB"}
    headers=[]
    for col in display.columns:
        if col in ("DATA","DIA"):
            headers.append(f'<th>{col}</th>')
        elif col == "SALDO TOTAL":
            headers.append('<th class="total-head">SOMA<div class="account-sub">SALDO TOTAL</div></th>')
        else:
            is_itau=col.endswith("ITAÚ"); logo=LOGO_ITAU if is_itau else LOGO_BB; css="bank-itau" if is_itau else "bank-bb"
            label=col.replace(" ITAÚ","").replace(" BB",""); sub=account_map.get(col,"ITAÚ" if is_itau else "BB")
            headers.append(f'<th class="{css}"><div class="bank-head-line"><span>{label}</span><img class="bank-logo" src="{logo}"></div><div class="account-sub">{sub}</div></th>')
    body=[]
    for _,row in display.iterrows():
        cells=[]
        for col in display.columns:
            if col in ("DATA","DIA"): cells.append(f'<td>{row[col]}</td>')
            else:
                val=float(row[col]) if pd.notna(row[col]) else 0.0; cls="total-cell" if col=="SALDO TOTAL" else ""
                cells.append(f'<td class="{cls}">{brl(val)}</td>')
        body.append('<tr>'+''.join(cells)+'</tr>')
    html='<div class="software-card"><div class="software-card-head"><div class="software-card-title">Saldos por Banco e Empresa</div><div class="software-card-note">Dias úteis • sem lançamento = R$ 0,00</div></div><div class="software-table-wrap"><table class="software-table"><thead><tr>'+''.join(headers)+'</tr></thead><tbody>'+''.join(body)+'</tbody></table></div></div>'
    st.markdown(html, unsafe_allow_html=True)


def render_monthly_software_table(monthly: pd.DataFrame) -> None:
    headers=''.join(f'<th>{c.upper()}</th>' for c in monthly.columns); body=[]
    for _,row in monthly.iterrows():
        cells=[]
        for col in monthly.columns:
            val=row[col]
            if col=="Mês": cells.append(f'<td>{val}</td>')
            elif col=="% Variação":
                txt="—" if pd.isna(val) else (f'{val:.2f}%'.replace('.',',')); cells.append(f'<td class="{_money_class(0 if pd.isna(val) else float(val))}">{txt}</td>')
            else:
                cls=_money_class(float(val)) if col=="Variação" else ""; cells.append(f'<td class="{cls}">{brl(val)}</td>')
        body.append('<tr>'+''.join(cells)+'</tr>')
    html='<div class="software-card"><div class="software-card-head"><div class="software-card-title">Consolidado por Mês</div><div class="software-card-note">Abertura, fechamento e evolução mensal</div></div><div class="software-table-wrap"><table class="software-table month-table"><thead><tr>'+headers+'</tr></thead><tbody>'+''.join(body)+'</tbody></table></div></div>'
    st.markdown(html, unsafe_allow_html=True)


def page_dashboard() -> None:
    hero("Visão Geral", "Acompanhe os saldos por banco, empresa e o consolidado mensal.")
    if not password_gate():
        return
    try:
        contas, saldos = load_database(st.session_state.get("db_refresh", 0))
    except Exception as exc:
        st.error(str(exc)); return
    if saldos.empty or saldos["DATA_DT"].dropna().empty:
        st.info("Ainda não há saldos gravados para exibir."); return

    history = saldos.dropna(subset=["DATA_DT", "SALDO"]).copy()
    aliases = contas[["BANCO", "CONTA", "APELIDO", "ORDEM"]].copy()
    aliases["K"] = aliases["BANCO"].map(key_part) + "|" + aliases["CONTA"].map(key_part)
    history["K"] = history["BANCO"].map(key_part) + "|" + history["CONTA"].map(key_part)
    history = history.merge(aliases[["K", "APELIDO", "ORDEM"]], on="K", how="left")
    history["APELIDO"] = history["APELIDO"].fillna(history["CONTA"])
    history["EMPRESA_GRUPO"] = history.apply(lambda r: company_group(str(r["APELIDO"]), str(r["EMPRESA"]), str(r["CONTA"])), axis=1)
    history["BANCO_GRUPO"] = history["BANCO"].map(bank_group)

    min_date, max_date = history["DATA_DT"].min().date(), history["DATA_DT"].max().date()
    f1, f2 = st.columns(2)
    with f1: start_date = st.date_input("Data inicial", value=min_date, min_value=min_date, max_value=max_date, format="DD/MM/YYYY")
    with f2: end_date = st.date_input("Data final", value=max_date, min_value=min_date, max_value=max_date, format="DD/MM/YYYY")
    if start_date > end_date:
        st.error("A data inicial não pode ser maior que a data final."); return

    period = history[(history["DATA_DT"].dt.date >= start_date) & (history["DATA_DT"].dt.date <= end_date)].copy()
    period["COLUNA"] = period.apply(lambda r: f'{r["EMPRESA_GRUPO"]} ITAÚ' if r["BANCO_GRUPO"] == "Itaú" else f'{r["EMPRESA_GRUPO"]} BB', axis=1)
    column_order = ["ÚNICA ITAÚ","ÚNICA BB","MERCADO ITAÚ","MERCADO BB","V&T ITAÚ","V&T BB","ÉTICA ITAÚ","ÉTICA BB","DT TINTAS ITAÚ","DT TINTAS BB","DAUTO ITAÚ","DAUTO BB"]
    present = [c for c in column_order if c in set(history["COLUNA"] if "COLUNA" in history.columns else period["COLUNA"])]
    # Preserve the standard business columns even when the selected range has no launch.
    known_groups = set(period["COLUNA"].dropna()) if not period.empty else set()
    present = [c for c in column_order if c in known_groups or c in {"ÚNICA ITAÚ","ÚNICA BB","MERCADO ITAÚ","MERCADO BB","V&T ITAÚ","V&T BB","ÉTICA ITAÚ","ÉTICA BB","DT TINTAS ITAÚ","DT TINTAS BB"}]
    extras = sorted([c for c in known_groups if c not in present]); present += extras

    business_days = pd.date_range(start=start_date, end=end_date, freq="B")
    raw_matrix = period.pivot_table(index="DATA_DT", columns="COLUNA", values="SALDO", aggfunc="sum") if not period.empty else pd.DataFrame()
    daily_matrix = raw_matrix.reindex(index=business_days, columns=present, fill_value=0).fillna(0)
    daily_matrix["SALDO TOTAL"] = daily_matrix.sum(axis=1)

    latest_total = float(daily_matrix.iloc[-1]["SALDO TOTAL"]) if not daily_matrix.empty else 0.0
    latest_date = daily_matrix.index[-1].strftime("%d/%m/%Y") if not daily_matrix.empty else "—"
    st.markdown(
        f"""
        <div style="display:flex;justify-content:flex-end;margin:.15rem 0 .9rem;">
          <div style="width:min(100%,390px);background:linear-gradient(135deg,#ffffff 0%,#f0fbf7 100%);border:1px solid #cfe8dd;border-radius:16px;padding:15px 18px;box-shadow:0 6px 18px rgba(16,42,67,.07);">
            <div style="font-size:11px;font-weight:800;letter-spacing:.06em;color:#648277;text-transform:uppercase;">Saldo da última data</div>
            <div style="display:flex;align-items:end;justify-content:space-between;gap:14px;margin-top:5px;">
              <div style="font-size:26px;line-height:1;font-weight:900;color:#08785a;font-variant-numeric:tabular-nums;">{brl(latest_total)}</div>
              <div style="font-size:12px;font-weight:700;color:#607b72;white-space:nowrap;">{latest_date}</div>
            </div>
          </div>
        </div>
        """, unsafe_allow_html=True
    )

    display = daily_matrix.copy()
    weekday = {0:"Seg",1:"Ter",2:"Qua",3:"Qui",4:"Sex",5:"Sáb",6:"Dom"}
    display.insert(0, "DIA", [weekday[d.weekday()] for d in display.index])
    display.insert(0, "DATA", [d.strftime("%d/%m/%Y") for d in display.index])
    display = display.reset_index(drop=True)
    render_daily_software_table(display)
    st.caption("DAUTO Serviços (conta 98530-8) permanece incorporada à ÉTICA Itaú, conforme a regra do sistema.")

    # Consolidado mensal é independente do filtro da tabela diária.
    # Ele usa todo o histórico disponível no banco, mantendo-se sempre visível.
    all_period = history.copy()
    actual_daily = all_period.groupby("DATA_DT", as_index=False)["SALDO"].sum().sort_values("DATA_DT")
    actual_daily["ANO"] = actual_daily["DATA_DT"].dt.year; actual_daily["MES"] = actual_daily["DATA_DT"].dt.month
    names={1:"Janeiro",2:"Fevereiro",3:"Março",4:"Abril",5:"Maio",6:"Junho",7:"Julho",8:"Agosto",9:"Setembro",10:"Outubro",11:"Novembro",12:"Dezembro"}
    rows=[]
    for (year,month),grp in actual_daily.groupby(["ANO","MES"], sort=True):
        grp=grp.sort_values("DATA_DT"); initial=float(grp.iloc[0]["SALDO"]); final=float(grp.iloc[-1]["SALDO"]); variation=final-initial
        rows.append({"Mês":f"{names[int(month)]}/{int(year)}","Saldo inicial":initial,"Saldo final":final,"Variação":variation,"% Variação":(variation/initial*100) if initial else None,"Saldo médio":float(grp["SALDO"].mean())})
    monthly=pd.DataFrame(rows)
    if monthly.empty:
        st.info("Ainda não há lançamentos históricos para montar o consolidado mensal.")
    else:
        render_monthly_software_table(monthly)

    with st.expander("Ver composição das contas"):
        detail=period[["DATA_DT","EMPRESA","BANCO","AGENCIA","CONTA","APELIDO","EMPRESA_GRUPO","SALDO"]].copy()
        detail["DATA_DT"]=detail["DATA_DT"].dt.strftime("%d/%m/%Y")
        detail.columns=["Data","Empresa original","Banco","Agência","Conta","Apelido","Empresa consolidada","Saldo"]
        st.dataframe(detail, hide_index=True, use_container_width=True, column_config={"Saldo":st.column_config.NumberColumn(format="R$ %.2f")})

def page_accounts() -> None:
    hero("Contas", "Cadastro usado para reconhecer os documentos e organizar o dashboard.")
    try:
        contas, _ = load_database(st.session_state.get("db_refresh", 0))
        st.dataframe(contas.sort_values("ORDEM"), hide_index=True, use_container_width=True)
        st.caption("O cadastro inicial é criado automaticamente sem duplicar BANCO + AGÊNCIA + CONTA.")
    except Exception as exc:
        st.warning(str(exc))
        st.dataframe(local_accounts(), hide_index=True, use_container_width=True)
        st.caption("Exibindo o cadastro padrão local enquanto o Google Sheets não está disponível.")


def main() -> None:
    st.set_page_config(page_title="Saldos Bancários", page_icon="🏦", layout="wide")
    inject_css()
    with st.sidebar:
        st.markdown(f'<div class="sidebar-brand"><div class="brand-circles"><img class="sidebar-logo-img" src="{LOGO_UNICA}"><img class="sidebar-logo-img" src="{LOGO_DAUTO}"></div><div class="brand-title">Grupo Dauto Tintas</div><div class="brand-subtitle">Controle diário de saldos</div></div>', unsafe_allow_html=True)
        page = st.radio("Navegação", ["Visão Geral", "Atualizar Saldos", "────────────", "Importar Histórico", "Contas"], label_visibility="collapsed")
        st.divider(); st.caption("Dados armazenados no Google Sheets")
    if page == "Visão Geral": page_dashboard()
    elif page == "Atualizar Saldos": page_update()
    elif page == "Importar Histórico": page_history_import()
    elif page == "Contas": page_accounts()
    else:
        st.session_state["noop"] = True
        st.info("Selecione uma opção do menu.")


if __name__ == "__main__":
    main()
